<script lang="ts">
 import {onMount} from 'svelte';
 import {Images,Settings as SettingsIcon,ShieldCheck,Upload,Plus,ArrowUpRight,FileText,ChevronLeft,ChevronRight,Check,CheckCheck,X,Play,Pause,Square,Download,LayoutGrid,ScanLine,Search,RefreshCw,AlertTriangle,Clock,HardDrive,ArrowLeft,RotateCcw,Trash2,ExternalLink,Image as ImageIcon,Copy,Sun,Moon,LoaderCircle,Keyboard,FolderOpen} from '@lucide/svelte';
 import {api,post,setToken,upload} from './services/api';
 import type {Job,Page,Region,Settings as SettingsType,Status} from './types';
 import CropViewer from './components/CropViewer.svelte';
 import Settings from './components/Settings.svelte';
 import ExportDialog from './components/ExportDialog.svelte';
 let jobs=$state<Job[]>([]),job=$state<Job|null>(null),pages=$state<Page[]>([]),regions=$state<Region[]>([]),gallery=$state<Region[]>([]),galleryTotal=$state(0);
 let selected=$state<string[]>([]),pageNumber=$state(1),view=$state('workspace'),pageFilter=$state('all'),pageSearch=$state(''),pageOffset=$state(0),galleryFilter=$state('all'),gallerySort=$state('page'),galleryOffset=$state(0),thumbSize=$state(200);
 let settings=$state<SettingsType>({mode:'balanced',format:'png',theme:'dark'}),models=$state<any[]>([]),showSettings=$state(false),showExport=$state(false),showShortcuts=$state(false),largeImage=$state<Region|null>(null);
 let loading=$state(true),busy=$state(false),error=$state(''),toast=$state(''),uploading=$state(false),uploadProgress=$state(0),uploadName=$state(''),dragging=$state(false),mode=$state('balanced'),password=$state(''),fileInput:HTMLInputElement;
 let exportState=$state<any>(null),modeDescription=$derived(mode==='native'?'Embedded images only':mode==='fast'?'Native PDF + OpenCV':mode==='maximum'?'Multiscale detection + available AI':'Native PDF + OpenCV + available AI');
 let eventSource:EventSource|null=null,lastSignature='',poll:any;
 let currentPage=$derived(pages.find(p=>p.number===pageNumber));
 let currentRegion=$derived((view==='workspace'?regions:gallery).find(r=>r.id===selected[0])||regions.find(r=>r.id===selected[0]));
 let visiblePages=$derived(pages.filter(p=>(!pageSearch||String(p.number).includes(pageSearch))&&(pageFilter==='all'||pageFilter==='review'&&p.review>0||pageFilter==='empty'&&p.status==='done'&&p.photographs===0||p.status===pageFilter)));
 let progress=$derived(job?job.processed/job.total*100:0);
 function fail(e:unknown){error=e instanceof Error?e.message:String(e);}
 function notify(message:string){toast=message;setTimeout(()=>toast='',3500);}
 function theme(value:string){document.documentElement.dataset.theme=value==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):value;}
 async function loadJobs(){jobs=await api('/jobs');}
 async function reloadPage(){if(!job)return;const id=job.id,num=pageNumber;const r=await api(`/jobs/${id}/regions?page=${num}&limit=500`);if(job?.id===id&&pageNumber===num){regions=r.items;selected=selected.filter(s=>regions.some(r=>r.id===s));}}
 async function reloadGallery(){if(!job)return;const id=job.id;const r=await api(`/jobs/${id}/regions?status=${view==='review'?'review':galleryFilter}&offset=${galleryOffset}&limit=48&sort=${gallerySort}`);if(job?.id===id){gallery=r.items;galleryTotal=r.total;}}
 async function refresh(){if(!job)return;const id=job.id;const p=await api<Page[]>(`/jobs/${id}/pages`);if(job?.id!==id)return;pages=p;await reloadPage();if(view!=='workspace')await reloadGallery();}
 async function openJob(value:Job){eventSource?.close();job=value;pageNumber=1;pageOffset=0;selected=[];view='workspace';lastSignature='';await refresh();eventSource=new EventSource(`/api/jobs/${value.id}/events`);eventSource.onmessage=(event)=>{const j=JSON.parse(event.data) as Job;if(job?.id!==j.id)return;job=j;const signature=`${j.processed}:${j.photographs}:${JSON.stringify(j.counts)}:${j.status}`;if(signature!==lastSignature){lastSignature=signature;refresh().catch(fail);}};eventSource.onerror=()=>{if(job?.status==='running')toast='Reconnecting to local progress…';};}
 async function home(){eventSource?.close();job=null;selected=[];exportState=null;await loadJobs();}
 async function importFiles(files:FileList|File[]|null){if(!files?.length||uploading)return;uploading=true;error='';try{let first:Job|null=null;for(const file of Array.from(files)){uploadName=file.name;uploadProgress=0;const next=await upload(file,mode,password,v=>uploadProgress=v);if(!first)first=next;if(files.length>1)await post(`/jobs/${next.id}/action`,{action:'start'});}password='';await loadJobs();if(first)await openJob(first);}catch(e){fail(e);}finally{uploading=false;if(fileInput)fileInput.value='';}}
 async function action(action:string){if(!job||busy)return;busy=true;try{job=await post(`/jobs/${job.id}/action`,{action,page:pageNumber});await refresh();}catch(e){fail(e);}finally{busy=false;}}
 async function navigate(number:number){pageNumber=number;selected=[];await reloadPage();}
 async function changeView(next:string){view=next;selected=[];galleryOffset=0;if(next!=='workspace')await reloadGallery();}
 function select(id:string,multi=false){selected=multi?(selected.includes(id)?selected.filter(x=>x!==id):[...selected,id]):[id];}
 async function edit(changes:any[],create?:any){if(!job)return;try{const r=await post<Region[]>(`/jobs/${job.id}/edits`,{changes,create});await refresh();job=await api(`/jobs/${job.id}`);if(create)selected=[r.at(-1)!.id];}catch(e){fail(e);}}
 async function setStatus(status:Status,ids=selected){await edit(ids.map(id=>({id,status})));if(view==='review'){selected=[];await reloadGallery();}}
 async function editBox(id:string,bbox:number[]){const r=regions.find(r=>r.id===id);await edit([{id,bbox,revision:r?.revision}]);}
 async function undo(redo=false){if(!job)return;try{await post(`/jobs/${job.id}/history`,{redo});await refresh();}catch(e){fail(e);}}
 async function split(){if(!currentRegion)return;const r=currentRegion,b=r.bbox,mid=(b[0]+b[2])/2;await edit([{id:r.id,bbox:[b[0],b[1],mid,b[3]]}],{page:r.page,bbox:[mid,b[1],b[2],b[3]]});}
 async function merge(){const chosen=regions.filter(r=>selected.includes(r.id));if(chosen.length<2)return;const b=[Math.min(...chosen.map(r=>r.bbox[0])),Math.min(...chosen.map(r=>r.bbox[1])),Math.max(...chosen.map(r=>r.bbox[2])),Math.max(...chosen.map(r=>r.bbox[3]))];await edit(chosen.map(r=>({id:r.id,status:'rejected'})),{page:pageNumber,bbox:b});}
 async function startExport(options:any){if(!job)return;try{exportState=await post(`/jobs/${job.id}/exports`,options);showExport=false;}catch(e){fail(e);}}
 async function openRegion(r:Region){view='workspace';pageNumber=r.page;pageOffset=Math.floor((r.page-1)/40)*40;await reloadPage();selected=[r.id];}
 function imageUrl(r:Region,thumb=true){return `/api/jobs/${r.job_id}/regions/${r.id}/image?thumb=${thumb}&v=${r.revision}`;}
 async function removeJob(value:Job){if(!confirm(`Remove “${value.name}” and its cached previews? Exported files are kept.`))return;try{await api(`/jobs/${value.id}`,{method:'DELETE'});await loadJobs();}catch(e){fail(e);}}
 function duration(seconds:number|null){if(seconds===null)return 'Estimating…';if(seconds<60)return `${Math.round(seconds)}s`;return `${Math.floor(seconds/60)}m ${Math.round(seconds%60)}s`;}
 function keydown(e:KeyboardEvent){if((e.target as HTMLElement).matches('input,select,textarea')||showSettings||showExport)return;if(e.key==='Escape'){largeImage=null;showShortcuts=false;selected=[];return;}if(!job)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(e.key.toLowerCase()==='a'&&!e.metaKey&&!e.ctrlKey&&selected.length){e.preventDefault();setStatus('accepted');}if(e.key.toLowerCase()==='r'&&selected.length)setStatus('rejected');if(e.key==='Delete'||e.key==='Backspace'){if(selected.length){e.preventDefault();setStatus('rejected');}}if(e.key==='ArrowRight'&&pageNumber<job.total)navigate(pageNumber+1);if(e.key==='ArrowLeft'&&pageNumber>1)navigate(pageNumber-1);if(e.key===']'||e.key==='['){const list=view==='workspace'?regions:gallery;const index=list.findIndex(r=>r.id===selected[0]);const next=e.key===']'?Math.min(list.length-1,index+1):Math.max(0,index-1);if(list[next])selected=[list[next].id];}}
 onMount(()=>{(async()=>{try{const state=await api('/session');setToken(state.token);settings=state.settings;mode=settings.mode;models=state.models;theme(settings.theme);await loadJobs();}catch(e){fail(e);}finally{loading=false;}})();poll=setInterval(async()=>{if(['running','queued'].includes(exportState?.status)){try{exportState=await api(`/exports/${exportState.id}`);if(exportState.status==='completed')notify(`${exportState.total} photographs exported`);}catch(e){fail(e);}}},1000);return()=>{eventSource?.close();clearInterval(poll);};});
</script>

<svelte:window onkeydown={keydown}/>
<input class="hidden-input" type="file" accept=".pdf,application/pdf" multiple bind:this={fileInput} onchange={(e)=>importFiles(e.currentTarget.files)}/>
<div class="app-shell">
 <header class="app-header"><button class="brand" onclick={()=>home().catch(fail)}><span class="brand-icon"><Images size={23}/></span><span>PDF Image Extractor</span><span class="version">LOCAL</span></button><div class="header-actions"><span class="local-status"><span class="status-dot"></span>On your computer</span><span class="header-divider"></span><button class="icon-button" title="Keyboard shortcuts" aria-label="Keyboard shortcuts" onclick={()=>showShortcuts=true}><Keyboard size={18}/></button><button class="icon-button" title="Settings" aria-label="Settings" onclick={async()=>{try{models=(await api('/models')).models;showSettings=true;}catch(e){fail(e);}}}><SettingsIcon size={19}/></button></div></header>
 {#if error}<div class="error-banner" role="alert"><AlertTriangle size={18}/><span>{error}</span><button aria-label="Dismiss error" onclick={()=>error=''}><X size={16}/></button></div>{/if}
 {#if loading}<div class="loading-screen"><LoaderCircle class="spin" size={28}/><p>Connecting to the local workspace…</p></div>
 {:else if !job}
 <main class="dashboard"><div class="dashboard-heading"><div class="eyebrow">YOUR LOCAL PHOTO WORKSPACE</div><h1>Every photograph.<br/><span>Out of the PDF.</span></h1><p>Extract original images, refine the boundaries, and keep every detail.<br/>Private by design. Processed entirely on this computer.</p></div>
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  <div class:dragging class="upload-zone" ondragover={(e)=>{e.preventDefault();dragging=true;}} ondragleave={()=>dragging=false} ondrop={(e)=>{e.preventDefault();dragging=false;importFiles(e.dataTransfer?.files||null);}}>
   <div class="upload-illustration"><div class="mini-sheet back"></div><div class="mini-sheet front"><div class="mini-photo tall"></div><div class="mini-photo"></div><div class="mini-photo"></div></div><span class="upload-circle"><Plus size={18}/></span></div>
   <h2>{uploading?'Bringing your document in…':'Drop your PDF here'}</h2><p>{uploading?uploadName:'Photography books, portfolios, magazines, and everything in between.'}</p>
   {#if uploading}<div class="upload-progress"><div style:width={`${uploadProgress}%`}></div></div><span class="help">{Math.round(uploadProgress)}% uploaded {uploadProgress===100?'· validating PDF':''}</span>{:else}<button class="primary" onclick={()=>fileInput.click()}><Upload size={17}/>Browse files</button><span class="upload-note">PDF files · multiple documents supported · up to 4 GB each</span>{/if}
  </div>
  <div class="import-controls"><label class="mode-control">{@render SlidersIcon()}<span>Processing mode</span><select bind:value={mode}><option value="native">Native only</option><option value="fast">Fast</option><option value="balanced">Balanced</option><option value="maximum">Maximum accuracy</option></select></label><span class="help">{modeDescription}</span><details class="password-disclosure"><summary>Protected PDF?</summary><label class="field">Document password<input type="password" bind:value={password} autocomplete="off" placeholder="Used only to unlock your local copy"/></label></details></div>
  <section class="recent-section"><div class="section-title"><h2>Recent documents <span>{jobs.length}</span></h2><button class="text-button" onclick={()=>loadJobs().catch(fail)}><RefreshCw size={14}/>Refresh</button></div>
  {#if jobs.length}<div class="job-list">{#each jobs as item}<div class="job-row"><button class="job-open" onclick={()=>openJob(item).catch(fail)}><span class="document-icon"><FileText size={22}/></span><span class="job-name"><strong>{item.name}</strong><small>{item.total} pages <span>·</span> {item.photographs} photographs <span>·</span> {new Date(item.created*1000).toLocaleDateString()}</small></span><span class={`badge ${item.status}`}>{item.status}</span><ChevronRight size={18}/></button><button class="icon-button subtle" title="Remove document" aria-label={`Remove ${item.name}`} onclick={()=>removeJob(item)}><Trash2 size={15}/></button></div>{/each}</div>{:else}<div class="empty-recents"><FolderOpen size={22}/><span>Your documents and saved extraction jobs will appear here.</span></div>{/if}</section>
  <footer class="dashboard-footer"><span><ShieldCheck size={16}/>No cloud. No uploads. No subscriptions.</span><span>Native resolution whenever available.</span></footer>
 </main>
 {:else}
 <div class="document-bar"><div class="document-title"><button class="icon-button" aria-label="Back to documents" onclick={()=>home().catch(fail)}><ArrowLeft size={18}/></button><FileText size={19}/><div><h1>{job.name}</h1><span>{job.total} pages <span class="dot-separator">·</span> {job.settings.mode==='maximum'?'Maximum accuracy':job.settings.mode==='native'?'Native only':job.settings.mode[0].toUpperCase()+job.settings.mode.slice(1)} mode</span></div></div><div class="job-actions">{#if job.status==='running'||job.status==='queued'}<button disabled={busy} onclick={()=>action('pause')}><Pause size={15}/>Pause</button><button class="icon-button" title="Cancel processing" aria-label="Cancel processing" disabled={busy} onclick={()=>action('cancel')}><Square size={14}/></button>{:else if ['ready','paused','cancelled'].includes(job.status)}<button class="primary" disabled={busy} onclick={()=>action(job!.status==='ready'?'start':'resume')}><Play size={15}/>{job.status==='ready'?'Start extraction':'Resume extraction'}</button>{:else}<span class="complete-label"><CheckCheck size={16}/>Extraction complete</span>{/if}{#if job.failed}<button onclick={()=>action('retry')}><RefreshCw size={14}/>Retry {job.failed} failed</button>{/if}</div></div>
 <section class="progress-section"><div class="stats-grid"><div class="stat"><span class="stat-value">{job.processed}<small> / {job.total}</small></span><span class="stat-label">Pages processed</span></div><div class="stat"><span class="stat-value">{job.photographs}</span><span class="stat-label">Photographs detected</span></div><div class="stat"><span class="stat-value green">{job.counts.accepted||0}</span><span class="stat-label"><span class="tiny-dot green-bg"></span>Accepted</span></div><div class="stat"><span class="stat-value amber">{job.counts.review||0}</span><span class="stat-label"><span class="tiny-dot amber-bg"></span>Needs review</span></div><div class="processing-detail"><span class="engine-chip"><span class="status-dot"></span>{job.device}</span><span>{(job.engines||['Native PDF','OpenCV']).join(' + ')}</span></div></div><div class="progress-track"><div style:width={`${progress}%`}></div></div><div class="progress-caption"><span>{job.stage}{job.failed?` · ${job.failed} failed pages`:''}</span><span>{duration(job.elapsed)} elapsed {job.status==='running'?`· ${job.speed.toFixed(1)} pages/s · ${duration(job.eta)} remaining`:''}</span></div>{#if job.warnings.length}<details class="job-warnings"><summary><AlertTriangle size={13}/>{job.warnings.length} processing notice{job.warnings.length>1?'s':''}</summary>{#each job.warnings as warning}<p>{warning}</p>{/each}</details>{/if}</section>
 <nav class="workspace-tabs"><div><button class:active={view==='workspace'} onclick={()=>changeView('workspace')}><ScanLine size={16}/>Page workspace</button><button class:active={view==='gallery'} onclick={()=>changeView('gallery')}><LayoutGrid size={16}/>Photograph gallery<span>{job.photographs}</span></button><button class:active={view==='review'} onclick={()=>changeView('review')}><AlertTriangle size={15}/>Review queue<span class="amber">{job.counts.review||0}</span></button></div><button class="text-button" onclick={()=>fileInput.click()}><Plus size={15}/>Add PDF</button></nav>
 {#if view==='workspace'}
 <main class="workspace"><aside class="pages-panel"><div class="panel-label">PAGES<span>{visiblePages.length}</span></div><div class="page-search"><Search size={14}/><input aria-label="Find page" placeholder="Find page…" bind:value={pageSearch} oninput={()=>pageOffset=0}/></div><select class="page-filter" aria-label="Filter pages" bind:value={pageFilter} onchange={()=>pageOffset=0}><option value="all">All pages</option><option value="pending">Unprocessed</option><option value="done">Completed</option><option value="review">Needs review</option><option value="failed">Failed</option><option value="empty">No photographs</option></select><div class="page-thumbnails">{#each visiblePages.slice(pageOffset,pageOffset+40) as p}<button class:active={p.number===pageNumber} class="page-thumbnail" onclick={()=>navigate(p.number)}><div class="thumb-paper"><img src={`/api/jobs/${job.id}/pages/${p.number}/preview?thumb=true`} alt={`Page ${p.number}`} loading="lazy"/>{#if p.review}<span class="review-marker"></span>{/if}{#if p.status==='failed'}<span class="page-error-marker"><AlertTriangle size={16}/></span>{/if}</div><span class="thumbnail-caption"><span>{p.number}</span><span>{p.status==='done'?`${p.photographs} images`:p.status==='running'?'Processing':p.status==='failed'?'Failed':'Pending'}</span></span></button>{/each}</div>{#if visiblePages.length>40}<div class="pagination"><button disabled={pageOffset===0} onclick={()=>pageOffset-=40} aria-label="Previous thumbnails"><ChevronLeft size={16}/></button><span>{Math.floor(pageOffset/40)+1} / {Math.ceil(visiblePages.length/40)}</span><button disabled={pageOffset+40>=visiblePages.length} onclick={()=>pageOffset+=40} aria-label="Next thumbnails"><ChevronRight size={16}/></button></div>{/if}</aside>
 <section class="center-panel">{#if currentPage}<CropViewer jobId={job.id} page={currentPage} {regions} {selected} onSelect={select} onEdit={editBox} onCreate={(bbox)=>edit([],{page:pageNumber,bbox})} onHistory={undo} onSplit={split} onMerge={merge}/>{:else}<div class="center-empty">Loading page…</div>{/if}{#if currentPage?.error}<div class="page-error">{currentPage.error}</div>{/if}<div class="page-navigation"><button disabled={pageNumber===1} onclick={()=>navigate(pageNumber-1)}><ChevronLeft size={14}/>Previous</button><span>Page {pageNumber} of {job.total}</span><button disabled={pageNumber===job.total} onclick={()=>navigate(pageNumber+1)}>Next<ChevronRight size={14}/></button></div></section>
 <aside class="inspector"><div class="panel-label">{currentRegion?`PHOTOGRAPH ${String(currentRegion.ordinal).padStart(3,'0')}`:'PHOTOGRAPH DETAILS'}<span>{selected.length>1?`${selected.length} selected`:''}</span></div>
 {#if currentRegion}<button class="inspector-preview" title="View full resolution" onclick={()=>largeImage=currentRegion!}><img src={imageUrl(currentRegion)} alt="Selected photograph"/><span><ExternalLink size={13}/>Full resolution</span></button><div class="region-heading"><span class={`badge ${currentRegion.status}`}>{currentRegion.status==='review'?'Needs review':currentRegion.status==='accepted'?'Accepted':'Rejected'}</span><span class="muted">Page {currentRegion.page}</span></div><dl class="region-details"><dt>Estimated output</dt><dd class="resolution">{currentRegion.dimensions[0]} × {currentRegion.dimensions[1]}<span>px</span></dd>{#if currentRegion.source}<dt>Embedded source</dt><dd>{currentRegion.source.width} × {currentRegion.source.height} px</dd>{/if}<dt>Detection</dt><dd>{currentRegion.method}</dd><dt>Detection score</dt><dd>{currentRegion.confidence!==null?`${(currentRegion.confidence*100).toFixed(1)}% · heuristic`:'Manual selection'}</dd><dt>Classification</dt><dd>{currentRegion.classification}</dd><dt>Source extraction</dt><dd>{currentRegion.source?.safe?'Available · visible crop verified':'Rendered fallback'}</dd><dt>Aspect ratio</dt><dd>{((currentRegion.bbox[2]-currentRegion.bbox[0])/(currentRegion.bbox[3]-currentRegion.bbox[1])).toFixed(3)} : 1</dd></dl>
 <details class="crop-coordinates"><summary>Crop coordinates <span>PDF points</span></summary><div class="coordinate-grid">{#each ['Left','Top','Right','Bottom'] as label,i}<label>{label}<input type="number" step=".1" value={currentRegion.bbox[i].toFixed(1)} onchange={(e)=>{const b=[...currentRegion!.bbox];b[i]=Number(e.currentTarget.value);editBox(currentRegion!.id,b);}}/></label>{/each}</div></details>
 {#if currentRegion.reasons.length}<details class="region-notes"><summary>Detection notes ({currentRegion.reasons.length})</summary>{#each currentRegion.reasons as reason}<p>{reason}</p>{/each}</details>{/if}{#if currentRegion.duplicate}<div class="duplicate-note"><Copy size={14}/><span>{currentRegion.duplicate.kind} · page {currentRegion.duplicate.page}</span></div>{/if}
 <div class="review-actions"><button class="accept-button" onclick={()=>setStatus('accepted')}><Check size={16}/>Accept {selected.length>1?`(${selected.length})`:'crop'}<kbd>A</kbd></button><button onclick={()=>setStatus('review')}><RotateCcw size={15}/>{currentRegion.status==='rejected'?'Restore to review':'Mark for review'}</button><button class="reject-button" onclick={()=>setStatus('rejected')}><X size={16}/>Reject<kbd>R</kbd></button></div><div class="secondary-actions"><button class="text-button" onclick={()=>editBox(currentRegion!.id,currentRegion!.original_bbox)}><RotateCcw size={13}/>Reset crop</button><a class="text-button" href={imageUrl(currentRegion,false)+`&download=true&format=${job.settings.format}`}><Download size={14}/>Download</a></div>
 {:else}<div class="inspector-empty"><ScanLine size={32}/><h3>Select a photograph</h3><p>Click a boundary on the page to inspect the image or adjust its crop.</p><p class="help">Missing an image? Use the + tool below the page to draw a new crop.</p></div>{/if}<div class="inspector-bottom"><button class="text-button" disabled={job.status==='running'||job.status==='queued'} onclick={()=>action('redetect')}><RefreshCw size={14}/>Re-run page detection</button><span>Manual corrections are preserved.</span></div></aside>
 </main>
 {:else}
 <main class="gallery-workspace"><div class="gallery-toolbar"><div><h2>{view==='review'?'Review the uncertain ones.':'Your photographs.'}</h2><span>{galleryTotal} regions {view==='review'?'· A to accept, R to reject, [ / ] to move':''}</span></div><div class="gallery-controls">{#if view==='gallery'}<select aria-label="Filter photographs" bind:value={galleryFilter} onchange={()=>{galleryOffset=0;reloadGallery();}}><option value="all">All statuses</option><option value="accepted">Accepted</option><option value="review">Needs review</option><option value="rejected">Rejected</option></select>{/if}<select aria-label="Sort photographs" bind:value={gallerySort} onchange={()=>reloadGallery()}><option value="page">Page order</option><option value="resolution">Highest resolution</option><option value="confidence">Lowest confidence</option></select><input aria-label="Thumbnail size" type="range" min="150" max="300" bind:value={thumbSize}/></div></div>
 <div class="bulk-bar"><label class="check-field"><input type="checkbox" checked={gallery.length>0&&gallery.every(r=>selected.includes(r.id))} onchange={(e)=>selected=e.currentTarget.checked?gallery.map(r=>r.id):[]}/>Select this page</label><span>{selected.length} selected</span><button disabled={!selected.length} onclick={()=>setStatus('accepted')}><Check size={14}/>Accept</button><button disabled={!selected.length} onclick={()=>setStatus('rejected')}><X size={14}/>Reject</button><button disabled={!selected.length} onclick={()=>setStatus('review')}><RotateCcw size={14}/>Restore</button><button disabled={!selected.length} onclick={()=>showExport=true}><Download size={14}/>Export selected</button></div>
 {#if gallery.length}<div class="gallery-grid" style:grid-template-columns={`repeat(auto-fill,minmax(${thumbSize}px,1fr))`}>{#each gallery as r}<article class:selected={selected.includes(r.id)} class="gallery-card"><button class="gallery-image" onclick={(e)=>select(r.id,e.shiftKey||e.metaKey||e.ctrlKey)} ondblclick={()=>largeImage=r} aria-label={`Select photograph ${r.ordinal} on page ${r.page}`}><img loading="lazy" src={imageUrl(r)} alt={`Photograph on page ${r.page}`}/><span class="selection-circle">{#if selected.includes(r.id)}<Check size={13}/>{/if}</span><span class={`gallery-status ${r.status}`}></span>{#if r.duplicate}<span class="duplicate-badge" title={r.duplicate.kind}><Copy size={13}/></span>{/if}</button><div class="gallery-caption"><div><strong>Page {r.page} <span>· {String(r.ordinal).padStart(3,'0')}</span></strong><small>{r.dimensions[0]} × {r.dimensions[1]}</small></div><button class="icon-button" title="Edit on page" aria-label="Edit crop on page" onclick={()=>openRegion(r)}><ArrowUpRight size={17}/></button></div><div class="gallery-card-actions"><button class="text-button" onclick={()=>setStatus('accepted',[r.id])}><Check size={13}/>Accept</button><button class="text-button" onclick={()=>setStatus('rejected',[r.id])}><X size={13}/>Reject</button><button class="text-button" aria-label="View full resolution" onclick={()=>largeImage=r}><ExternalLink size={13}/></button></div></article>{/each}</div>{:else}<div class="gallery-empty"><CheckCheck size={38}/><h3>{view==='review'?'Nothing waiting for review':'No photographs here yet'}</h3><p>{view==='review'?'New uncertain detections will appear here as pages are processed.':'Start extraction or draw a crop in the page workspace.'}</p></div>{/if}
 <div class="gallery-pagination"><button disabled={galleryOffset===0} onclick={()=>{galleryOffset-=48;selected=[];reloadGallery();}}><ChevronLeft size={16}/>Previous</button><span>{galleryTotal?galleryOffset+1:0}–{Math.min(galleryTotal,galleryOffset+48)} of {galleryTotal}</span><button disabled={galleryOffset+48>=galleryTotal} onclick={()=>{galleryOffset+=48;selected=[];reloadGallery();}}>Next<ChevronRight size={16}/></button></div></main>
 {/if}
 <footer class="export-bar"><div class="export-ready"><span class="export-icon"><Images size={20}/></span><div><strong>{job.counts.accepted||0} photographs ready</strong><span>Source-aware quality <span>·</span> {job.settings.format.toUpperCase()} export</span></div></div><div class="export-bar-actions">{#if exportState}<div class="export-status" class:failed={exportState.status==='failed'}>{#if ['running','queued'].includes(exportState.status)}<LoaderCircle class="spin" size={14}/>Exporting {exportState.completed||0} / {exportState.total}{:else if exportState.status==='completed'}<a href={`/api/exports/${exportState.id}/download`}><Download size={15}/>Download ZIP</a><span title={exportState.path}>Saved to {exportState.path?.split('/').slice(-1)}</span>{:else}<span>{exportState.error}</span>{/if}</div>{/if}<button class="primary export-button" disabled={!job.photographs||['running','queued'].includes(exportState?.status)} onclick={()=>showExport=true}><Download size={17}/>Export photographs</button></div></footer>
 {/if}
</div>
{#if showSettings}<Settings value={settings} {models} onclose={()=>showSettings=false} onsave={(v)=>{settings=v;mode=v.mode;theme(v.theme);notify('Settings saved');}} onerror={fail}/>{/if}
{#if showExport&&job}<ExportDialog {job} {selected} onclose={()=>showExport=false} onexport={startExport}/>{/if}
{#if toast}<div class="toast" role="status"><Check size={16}/>{toast}</div>{/if}
{#if largeImage}<div class="lightbox" role="dialog" aria-label="Full resolution photograph" aria-modal="true" tabindex="-1"><div><span>Page {largeImage.page} · Photograph {largeImage.ordinal} · Full resolution</span><button class="icon-button" onclick={()=>largeImage=null} aria-label="Close full resolution"><X size={22}/></button></div><section><img src={imageUrl(largeImage,false)} alt="Photograph at original output resolution"/></section></div>{/if}
{#if showShortcuts}<div class="modal-backdrop"><div class="modal shortcuts" role="dialog" aria-label="Keyboard shortcuts" aria-modal="true" tabindex="-1"><div class="modal-head"><h2>Keyboard shortcuts</h2><button class="icon-button" aria-label="Close shortcuts" onclick={()=>showShortcuts=false}><X size={20}/></button></div><dl><dt>Accept selection</dt><dd><kbd>A</kbd></dd><dt>Reject selection</dt><dd><kbd>R</kbd> / <kbd>Delete</kbd></dd><dt>Previous / next photograph</dt><dd><kbd>[</kbd> <kbd>]</kbd></dd><dt>Previous / next page</dt><dd><kbd>←</kbd> <kbd>→</kbd></dd><dt>Undo / redo</dt><dd><kbd>⌘Z</kbd> <kbd>⌘⇧Z</kbd></dd><dt>Multi-select</dt><dd><kbd>Shift-click</kbd></dd><dt>Clear selection / close preview</dt><dd><kbd>Esc</kbd></dd></dl></div></div>{/if}

{#snippet SlidersIcon()}<ScanLine size={16}/>{/snippet}
